#include <string>
#include <iostream>

int main() {
    std::string str = "Hello, World!";  // Initial string with SSO possible if short
    auto insertPos = str.begin() + 7;  // Iterator pointing to 'W'
    std::string additional = "Inserted ";
    str.insert(insertPos, additional.begin(), additional.end());  // Inserts "Inserted " before 'W'
    std::cout << str << std::endl;  // Outputs: "Hello, Inserted World!"
    return 0;
}
